using System;
using System.IO;
using System.Linq;
using MET.Core;
// G0 observes current rules. Script choices are test inputs, never balance changes.
class WildG0Program {
 static V checks=V.Arr(),commands=V.Arr(),trace=V.Arr(),completions=V.Arr(),opportunities=V.Arr();
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks.Add(name);Console.WriteLine("PASS "+name);}
 static void Command(string error,string name){Check(error=="",name+(error==""?"":" : "+error));}
 static string Tile(Game g)=>g.s["cells"].Keys.Where(id=>g.s["cells"][id]["building"].Text==""&&!g.s["cells"][id]["traits"].Contains("tile.water")).OrderBy(id=>Hex.distance("0,1",id)).ThenBy(id=>id,StringComparer.Ordinal).First();
 static V Status(CitySession city,double second){var g=city.FocusedGame;var affordable=V.Arr();foreach(var id in g.c.v040["progression"]["tier1"])if(g.s["currency"].Double>=g.c.projects[id]["cost"].Double)affordable.Add(id);
  var stock=V.Map();foreach(string r in new[]{"food","material","goods"})stock[r]=g.inventory_total(r);
  return V.Map("active_second",second,"local_months",g.s["local_hours"],"dt",g.s["dt"],"currency",g.s["currency"],"stock",stock,"flows_per_month",g.s["metrics"].Get("flows",V.Map()).Duplicate(true),"population",g.s["metrics"].Get("population",0),"housing",g.s["metrics"].Get("housing",0),"energy_supply",g.s["metrics"].Get("energy",0),"energy_demand",g.s["metrics"].Get("energy_need",0),"queue",Construction.queue(g).Duplicate(true),"affordable_base_types",affordable,"pending_rewards",Bonus.pending(g).Count,"pause_reason",g.s["beta_time"].Get("pause_reason",""),"city_paused",city.s["paused"]);
 }
 static void Build(CitySession city,string node,double second){var g=city.FocusedGame;string tile=Tile(g);var before=g.snapshot();string open=g.create_tender(V.Arr(tile),node);Check(open=="","script tender opens "+node);var offer=g.s["draft"]["offers"][0].Duplicate(true);var quote=Draft.offer_cost(g,offer);double cash=g.s["currency"].Double,material=g.inventory_total("material");string result=g.accept_offer(offer["id"].Text);city.AfterLocalCommand(before);string id=g.s["cells"][tile]["building"].Text;
  commands.Add(V.Map("active_second",second,"command","create_tender + accept_offer[0]","base",node,"tile",tile,"offer",offer,"quote",quote,"error",result,"project_id",id,"currency_before",cash,"currency_after",g.s["currency"],"material_before",material,"material_after",g.inventory_total("material")));
  Check(result=="","script construction accepted "+node);Check(Math.Abs(cash-g.s["currency"].Double-quote["currency"].Double)<1e-8,"quote cash matches accepted charge "+node);Check(Math.Abs(material-g.inventory_total("material"))<1e-8,"material is not prepaid at acceptance "+node);
 }
 static int Main(string[] args){try {
  string root=Path.GetFullPath(args.Length>1?args[1]:"build/wild-g0");Directory.CreateDirectory(root);var c=new Catalog(args.Length>0?args[0]:"content");var city=new CitySession(c,Path.Combine(root,"initial"));city.New(20261026,0,"MET Wild G0 工程基线");Command(city.BeginDistrict(0,"balanced"),"begin current balanced river district");var g=city.FocusedGame;string origin=g.s["origin_choices"][0].Text;var beforeOrigin=g.snapshot();Command(g.choose_origin(origin),"choose first offered origin "+origin);city.AfterLocalCommand(beforeOrigin);
  // All persistence stays under the caller-selected isolated evidence directory.
  Command(city.Save(),"write isolated initial save");var saved=city.snapshot().ToJson(false,true);var restored=new CitySession(c,Path.Combine(root,"roundtrip"));Command(restored.Restore(CityStore.read(c,CityStore.path(city.storageRoot))["state"]),"read and restore current CityStore format");Check(restored.snapshot()==V.Parse(saved),"current save roundtrip preserves complete city");Command(restored.Save(),"write isolated roundtrip save");
  string tile=Tile(g);var before=g.s.ToJson(false,true);var compiled=g.compiled.ToJson(false,true);var rng=g.s["rng"].ToJson(false,true);var plan=new Planning();var preview=plan.compare(g,"homestead",tile);Check(preview["ok"].Bool,"existing real-engine construction preview succeeds");Check(before==g.s.ToJson(false,true)&&compiled==g.compiled.ToJson(false,true)&&rng==g.s["rng"].ToJson(false,true),"preview preserves live state compiled rules inventory and RNG");
  Command(g.create_tender(V.Arr(tile),"homestead"),"quote fixture opens tender");var quoteState=g.s.ToJson(false,true);var quoted=Draft.offer_cost(g,g.s["draft"]["offers"][0]);Check(quoteState==g.s.ToJson(false,true),"quote reading preserves state and RNG");var offers=g.s["draft"]["offers"].ToJson(false,true);var afterDraw=g.s["rng"].ToJson(false,true);Command(g.cancel_draft(),"cancel retains current quote");Command(g.create_tender(V.Arr(tile),"homestead"),"reopen retained tender");Check(offers==g.s["draft"]["offers"].ToJson(false,true)&&afterDraw==g.s["rng"].ToJson(false,true),"retained quote and reopening preserve offer identities and RNG");Command(g.cancel_draft(),"close quote fixture");
  // Reset to the saved pre-test state: focused assertions cannot contaminate pacing.
  Command(city.Restore(V.Parse(saved)),"restore pristine initial fixture before replay");g=city.FocusedGame;
  trace.Add(Status(city,0));Build(city,"homestead",0);city.s["paused"]=false;g.s["settings"]["user_paused"]=false;g.s["beta_time"]["pause_reason"]="";Command(Clock.set_mode(g,"advance"),"select existing advance speed");
  var known=V.Map();foreach(var p in g.s["projects"].Pairs)known[p.Key]=p.Value["status"];
  double second=0,spent=0,affordableSeconds=0,queueSeconds=0;long steps=0,segments=0;int previousRewards=0;
  while(second<720-1e-8){double requested=Math.Min(5,720-second);var result=city.Advance(requested);double used=result["external_seconds"].Double;steps+=result["steps"].Long;spent+=result["spent"].Double;if(used<=0)throw new Exception("Advance did not progress at "+second+": "+result["reason"].Text);segments++;if(g.s["currency"].Double>=75)affordableSeconds+=used;if(Construction.queue(g).Count>0)queueSeconds+=used;second+=used;int rewardCount=Bonus.pending(g).Count;if(rewardCount!=previousRewards){opportunities.Add(V.Map("observed_active_second",second,"kind","pending_reward_count_changed","before",previousRewards,"after",rewardCount,"pending",Bonus.pending(g).Duplicate(true)));previousRewards=rewardCount;}
   foreach(var p in g.s["projects"].Pairs){if(known.Get(p.Key,"").Text=="construction"&&p.Value["status"].Text=="running")completions.Add(V.Map("project_id",p.Key,"base",p.Value["def"],"observed_active_second",second,"local_months",g.s["local_hours"],"sampling_resolution_seconds",5));known[p.Key]=p.Value["status"];}
   if(Math.Abs(second-180)<1e-7)Build(city,"workshop",second);if(Math.Abs(second-360)<1e-7)Build(city,"neighborhood",second);
   if(Math.Abs(second%60)<1e-7||city.s["paused"].Bool)trace.Add(Status(city,second));
   if(city.s["paused"].Bool&&second<720-1e-7)throw new Exception("Actual mandatory pause before replay end at "+second+": "+result["reason"].Text);
  }
  Check(Math.Abs(second-720)<1e-6,"replay submits exactly 720 active seconds");Check(Math.Abs(g.s["local_hours"].Double-12)<1e-6,"advance mode reaches twelve existing local months");Check(completions.Count==3,"three scripted real constructions finish");Check(city.Validate()=="","final current city validates");Command(CityStore.write(city,Path.Combine(root,"final",CityStore.SAVE)),"write isolated final save");
  var report=V.Map("scope","G0 engineering current-game baseline; deterministic scripted input, not human gameplay acceptance or future Wild mechanics","seed",20261026,"utc",0,"landing",0,"specialization","balanced","origin",origin,"initial_save",Path.Combine(root,"initial",CityStore.SAVE),"final_save",Path.Combine(root,"final",CityStore.SAVE),"speed","advance","acceleration",Clock.acceleration(g,"advance"),"active_seconds",second,"earth_seconds_per_month",c.beta["units"]["earth_seconds_per_month"],"earth_seconds_per_dt",c.beta["time"]["earth_seconds_per_dt"],"dt_spent",spent,"simulation_steps",steps,"submitted_segments",segments,"seconds_with_cash_for_all_three_base_types_sampled_at_segment_end",affordableSeconds,"seconds_with_nonempty_construction_queue_sampled_at_segment_end",queueSeconds,"opportunity_observations",opportunities,"commands",commands,"completion_observations",completions,"minute_trace",trace,"checks",checks,"human_acceptance","pending; automated affordability is not a meaningful-choice or fun verdict");File.WriteAllText(Path.Combine(root,"replay.json"),V.Map("seed",20261026,"utc",0,"landing",0,"specialization","balanced","origin",origin,"duration_active_seconds",720,"speed","advance","scheduled_builds",V.Arr(V.Map("active_second",0,"base","homestead"),V.Map("active_second",180,"base","workshop"),V.Map("active_second",360,"base","neighborhood")),"offer_policy","first offered operator","tile_policy","empty dry land nearest 0,1 then ordinal tile id","initial_paused",true).ToJson(true));File.WriteAllText(Path.Combine(root,"evidence.json"),report.ToJson(true));Console.WriteLine("WILD G0 PASS "+checks.Count+" assertions; evidence "+Path.Combine(root,"evidence.json"));return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
